item.content:encoded:
.btn-primary {
  color: #f6f9fe;
  background-color:#313CEA !important;
  border-color: #313CEA !important;
}

/* ============================
   KREATAZZ – CLEAN THEME CSS
   ============================ */

/* 1. HEADER & NAVIGATION (dark header, white links) */
.ct-header,
.site-header,
header#header {
  position: relative;
  z-index: 20;
  background-color: #1f1f1f;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.ct-header .site-title,
.site-header .site-title,
header#header .site-title,
.ct-header .site-logo img {
  opacity: 1 !important;
  filter: none !important;
  visibility: visible !important;
}

.ct-header a,
.site-header a,
.menu a {
  color: #ffffff !important;
  text-decoration: none;
  transition: color 0.2s ease;
}

.ct-header a:hover,
.site-header a:hover,
.menu a:hover {
  color: var(--color-accent, #92D050) !important;
}

/* 2. "WHY KREATAZZ" SECTION (dark, neon cards only for that section) */
#why-kreatazz {
  background: radial-gradient(circle at top left, #0f0f0f 0%, #1a1a1a 100%);
  color: #fff;
  text-align: center;
  padding-top: 70px;
  padding-bottom: 70px;
  position: relative;
  overflow: hidden;
}

#why-kreatazz::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(0, 140, 255, 0.05),
    rgba(57, 255, 20, 0.03)
  );
  z-index: 0;
}

#why-kreatazz h2 {
  position: relative;
  z-index: 1;
  font-size: 38px;
  font-weight: 700;
  margin-bottom: 15px;
}

#why-kreatazz h2 span {
  color: #00B0F0;
}

#why-kreatazz p.intro {
  max-width: 760px;
  margin: 0 auto 50px;
  color: #cfd6d9;
  font-size: 17px;
  position: relative;
  z-index: 1;
}

.why-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 28px;
  position: relative;
  z-index: 1;
}

.why-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 40px 28px 36px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.3);
  transition: transform 0.35s ease, box-shadow 0.35s ease,
    border-color 0.35s ease;
  position: relative;
  overflow: hidden;
  opacity: 0;
  animation: fadeUp 0.7s ease forwards;
}

.why-card:nth-child(1) { animation-delay: 0.1s; }
.why-card:nth-child(2) { animation-delay: 0.25s; }
.why-card:nth-child(3) { animation-delay: 0.4s; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(15px); }
  to   { opacity: 1; transform: translateY(0); }
}

.why-card::before {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(
    circle,
    rgba(0, 140, 255, 0.12) 0%,
    rgba(57, 255, 20, 0.12) 60%,
    transparent 80%
  );
  transform: rotate(25deg);
  opacity: 0;
  transition: opacity 0.5s ease;
  z-index: 0;
}

.why-card:hover::before { opacity: 1; }

.why-card:hover {
  transform: translateY(-8px);
  border-color: #00B0F0;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.5);
}

.why-icon {
  margin-bottom: 16px;
  position: relative;
  z-index: 1;
  width: 70px;
  height: 70px;
  margin-left: auto;
  margin-right: auto;
}

.why-icon img {
  width: 70px;
  height: 70px;
  filter: drop-shadow(0 0 8px rgba(0, 176, 240, 0.5));
  transition: transform 0.4s ease, filter 0.4s ease;
}

.why-card:hover .why-icon img {
  transform: scale(1.08);
  filter: drop-shadow(0 0 10px rgba(57, 255, 20, 0.7));
}

.why-card h3 {
  font-size: 20px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 10px;
  position: relative;
  z-index: 1;
}

.why-card p {
  color: #cfd6d9;
  font-size: 15px;
  margin: 0;
  position: relative;
  z-index: 1;
}

@media (max-width: 768px) {
  #why-kreatazz h2 { font-size: 30px; }
}

/* 3. CONTACT FORM 7 – KREATAZZ CARD */
.kreatazz-contact-form {
  max-width: 960px;
  margin: 40px auto 60px;
  background: radial-gradient(circle at top left, #1F1F1F 0%, #151515 40%, #0c0c0c 100%);
  border-radius: 20px;
  padding: 40px 32px 32px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55);
  position: relative;
  overflow: hidden;
}

.kreatazz-contact-form::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,140,255,0.16), rgba(57,255,20,0.08));
  opacity: 0.6;
  mix-blend-mode: screen;
  pointer-events: none;
}

.kreatazz-contact-inner {
  position: relative;
  z-index: 1;
}

/* Grid for CF7 fields */
.k-row {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  margin-bottom: 10px;
}

.k-col-6 {
  flex: 0 0 calc(50% - 12px);
  max-width: calc(50% - 12px);
}

.k-col-full {
  flex: 0 0 100%;
  max-width: 100%;
}

@media (max-width: 768px) {
  .k-col-6 {
    flex-basis: 100%;
    max-width: 100%;
  }

  .kreatazz-contact-form {
    padding: 28px 20px 24px;
    margin: 24px auto 40px;
  }
}

/* Inputs / textarea */
.kreatazz-contact-form input[type="text"],
.kreatazz-contact-form input[type="email"],
.kreatazz-contact-form input[type="tel"],
.kreatazz-contact-form textarea {
  width: 100%;
  padding: 11px 14px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(15,15,15,0.9);
  color: #f5f5f5;
  font-size: 15px;
  line-height: 1.5;
  transition: border-color 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
}

.kreatazz-contact-form textarea {
  min-height: 150px;
  resize: vertical;
}

/* Placeholder color */
.kreatazz-contact-form ::placeholder {
  color: #a0acb5;
  opacity: 1;
}

/* Focus state */
.kreatazz-contact-form input:focus,
.kreatazz-contact-form textarea:focus {
  outline: none;
  border-color: #00B0F0;
  box-shadow: 0 0 0 1px #00B0F0, 0 0 0 4px rgba(0,176,240,0.25);
  background: rgba(8, 20, 30, 0.95);
}

/* Turnstile row */
.k-turnstile-row {
  justify-content: flex-start;
  margin-top: 6px;
  margin-bottom: 4px;
}

.k-turnstile-row .k-col-full {
  display: flex;
  justify-content: flex-start;
}

/* Submit button */
.kreatazz-contact-form .wpcf7-submit,
.kreatazz-contact-form input[type="submit"],
.kreatazz-contact-form .btn.btn-secondary {
  background: linear-gradient(135deg, #00B0F0, #008CFF);
  border: none;
  border-radius: 999px;
  padding: 10px 34px;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-size: 13px;
  box-shadow: 0 12px 24px rgba(0,140,255,0.45);
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.kreatazz-contact-form .wpcf7-submit:hover,
.kreatazz-contact-form input[type="submit"]:hover,
.kreatazz-contact-form .btn.btn-secondary:hover {
  background: linear-gradient(135deg, #39FF14, #00B0F0);
  transform: translateY(-1px);
  box-shadow: 0 18px 35px rgba(0,0,0,0.7);
}

/* CF7 messages */
.kreatazz-contact-form .wpcf7-response-output {
  margin: 18px 0 0;
  padding: 10px 14px;
  border-radius: 8px;
  border-width: 1px;
  font-size: 13px;
}

.kreatazz-contact-form .wpcf7-not-valid-tip {
  font-size: 12px;
  color: #ff6b6b;
  margin-top: 4px;
}

/* 4. FOOTER – TEXT & COLUMNS (DARK FOOTER ONLY) */

/* Base text in all footer widgets */
.ct-footer .widget,
.ct-footer .widget p,
.ct-footer .widget span,
.ct-footer .widget li {
  color: #d7e3ea !important;
  opacity: 1 !important;
  font-size: 15px;
  line-height: 1.6;
}

/* Footer titles */
.ct-footer .widget-title,
.ct-footer [data-title],
.ct-footer .widget h2,
.ct-footer .widget h3 {
  color: #ffffff !important;
  font-weight: 600;
  margin-bottom: 12px;
}

/* Footer menu links */
.ct-footer .widget_nav_menu a,
.ct-footer .widget_nav_menu a:visited {
  color: #eaf6ff !important;
  text-decoration: none !important;
  font-weight: 400;
}

.ct-footer .widget_nav_menu a:hover {
  color: #92D050 !important;
}

.ct-footer .widget_nav_menu li {
  margin-bottom: 6px;
}

/* Contact column special */
.ct-footer .ft-contact,
.ct-footer .ft-contact p,
.ct-footer .ft-contact strong,
.ct-footer .ft-contact span {
  color: #ffffff !important;
}

.ct-footer .ft-contact a {
  color: #eaf6ff !important;
}

.ct-footer .ft-contact a:hover {
  color: #92D050 !important;
}

/* Dark footer background only */
.ct-footer,
.ct-footer-inner,
[data-footer] {
  background-color: #0e0e0e !important;
}

.ct-footer [data-row] {
  background: transparent !important;
}

/* Equal-height footer columns */
[data-footer*="type-1"] .ct-footer [data-row*="bottom"] > div {
  display: flex;
  gap: 30px;
}

[data-footer*="type-1"] .ct-footer [data-row*="bottom"] > div > div {
  flex: 1 1 0;
  align-self: flex-start;
}

