					<section id="what-we-do" class="container overflow-hidden pb-5">
  <style>
    /* ===== What We Do — uniform cards + animations ===== */
    #what-we-do { padding-top: 30px; }
    #what-we-do h1 { font-size: 34px; margin: 0 0 14px; }
    #what-we-do h1 span { color: #0078BF; }

    .wwd-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 22px;
    }

    /* Card */
    .wwd-card {
      position: relative;
      border-radius: 14px;
      overflow: hidden;
      background: #0f1114;
      color: #fff;
      text-decoration: none;
      box-shadow: 0 10px 22px rgba(0,0,0,.25);
      transform: translateY(0);
      transition: transform .25s ease, box-shadow .25s ease;
      display: flex;
      flex-direction: column;
      min-height: 100%;
    }
    .wwd-card:hover {
      transform: translateY(-6px);
      box-shadow: 0 18px 34px rgba(0,0,0,.35);
    }

    /* Perfectly consistent media area */
    .wwd-media {
      position: relative;
      aspect-ratio: 16 / 10;                /* uniform crop */
      width: 100%;
      overflow: hidden;
    }
    .wwd-media img {
      width: 100%; height: 100%;
      object-fit: cover;                     /* crops nicely */
      transform: scale(1);
      transition: transform .6s ease;
      display: block;
    }
    .wwd-card:hover .wwd-media img { transform: scale(1.06); }

    /* Readable overlay for text */
    .wwd-overlay {
      position: absolute; inset: 0;
      background: linear-gradient(
        to top,
        rgba(0,0,0,.65) 0%,
        rgba(0,0,0,.15) 60%,
        rgba(0,0,0,0) 100%
      );
      pointer-events: none;
    }

    .wwd-body {
      padding: 14px 16px 16px;
    }
    .wwd-pill {
      display: inline-block;
      border: 1px solid rgba(255,255,255,.85);
      color: #fff;
      padding: 6px 14px;
      border-radius: 9999px;
      font-size: 12px;
      margin-top: -30px;           /* sits into the image area */
      margin-bottom: 10px;
      backdrop-filter: saturate(120%) blur(2px);
    }
    .wwd-title { font-size: 18px; margin: 6px 0 6px; color: #fff; }
    .wwd-desc  { font-size: 14px; color: #d7e3ea; margin: 0; }
    .wwd-card:hover .wwd-title { color: #92D050; } /* brand hover */

    /* Entrance animation */
    .wwd-card { opacity: 0; animation: wwd-fadeUp .6s ease forwards; }
    .wwd-card:nth-child(1){ animation-delay: .05s; }
    .wwd-card:nth-child(2){ animation-delay: .15s; }
    .wwd-card:nth-child(3){ animation-delay: .25s; }
    .wwd-card:nth-child(4){ animation-delay: .35s; }
    @keyframes wwd-fadeUp { from {opacity:0; transform:translateY(12px)} to {opacity:1; transform:translateY(0)} }

    /* Mobile: swipeable row with snap */
    @media (max-width: 991px){
      .wwd-grid{
        display: grid;
        grid-auto-flow: column;
        grid-auto-columns: 80%;
        overflow-x: auto;
        scroll-snap-type: x mandatory;
        gap: 16px;
        padding-bottom: 6px;
      }
      .wwd-card{ scroll-snap-align: start; }
    }

    @media (max-width: 640px){
      .wwd-grid{ grid-auto-columns: 88%; }
    }
  </style>

  <h1 class="h2 text-center pt-5">What <span> We Do</span>?</h1>
  <p class="text-center pb-5">
    Kreatazz Tech specializes in providing services and solutions to help businesses navigate the digital landscape and achieve their strategic goals.
  </p>

  <div class="wwd-grid">
    <!-- Card 1 -->
    <a class="wwd-card" href="#">
      <div class="wwd-media">
        <img src="https://kreatazz.tech/wp-content/uploads/2025/02/cm3.jpg" alt="Technology Partnership">
        <span class="wwd-overlay"></span>
      </div>
      <div class="wwd-body">
        <span class="wwd-pill">Digital Transformation</span>
        <h3 class="wwd-title">Modernize & Integrate</h3>
        <p class="wwd-desc">Integrate digital tech to streamline operations, improve efficiency, and stay competitive.</p>
      </div>
    </a>

    <!-- Card 2 -->
    <a class="wwd-card" href="#">
      <div class="wwd-media">
        <img src="https://kreatazz.tech/wp-content/uploads/2025/02/AM-1.jpg" alt="Business Strategies">
        <span class="wwd-overlay"></span>
      </div>
      <div class="wwd-body">
        <span class="wwd-pill">Business Strategies</span>
        <h3 class="wwd-title">Plan to Win</h3>
        <p class="wwd-desc">Advisory to define goals, roadmaps, and investments aligned to measurable outcomes.</p>
      </div>
    </a>

    <!-- Card 3 -->
    <a class="wwd-card" href="#">
      <div class="wwd-media">
        <img src="https://kreatazz.tech/wp-content/uploads/2025/02/AM-2.jpg" alt="Market Research">
        <span class="wwd-overlay"></span>
      </div>
      <div class="wwd-body">
        <span class="wwd-pill">Market Research</span>
        <h3 class="wwd-title">Insights & Trends</h3>
        <p class="wwd-desc">Understand customers and competition with data-driven insights to de-risk decisions.</p>
      </div>
    </a>

    <!-- Card 4 -->
    <a class="wwd-card" href="#">
      <div class="wwd-media">
        <img src="https://kreatazz.tech/wp-content/uploads/2025/01/ef95bb9617b61b42b669ffc0948c98ad.jpg" alt="Quantitative Results">
        <span class="wwd-overlay"></span>
      </div>
      <div class="wwd-body">
        <span class="wwd-pill">Quantitative Results</span>
        <h3 class="wwd-title">Metrics that Matter</h3>
        <p class="wwd-desc">Analytics and performance KPIs that translate into clear, tangible business value.</p>
      </div>
    </a>
  </div>
</section>
