					<section id="kreatazz-services" class="container py-5 overflow-hidden">
  <style>
    /* ====== KREATAZZ SERVICES ====== */
    #kreatazz-services {
      background: linear-gradient(180deg, #0f0f0f 0%, #1a1a1a 100%);
      color: #fff;
      position: relative;
      padding-top: 60px;
      padding-bottom: 60px;
    }

    #kreatazz-services h2 {
      font-size: 38px;
      font-weight: 700;
      text-align: center;
      margin-bottom: 50px;
    }
    #kreatazz-services h2 span { color: #00B0F0; }

    .srv-row {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 32px;
    }

    .srv-card {
      position: relative;
      background: rgba(255, 255, 255, 0.05);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 16px;
      overflow: hidden;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
      transform: translateY(0);
      transition: transform 0.35s ease, box-shadow 0.35s ease, border-color 0.35s ease;
    }

    .srv-card img {
      width: 100%;
      height: 200px;
      object-fit: cover;
      transition: transform 0.6s ease;
    }

    .srv-card:hover img {
      transform: scale(1.08);
    }

    .srv-body {
      padding: 20px 18px 70px;
      color: #e7eef2;
      background: linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,.6) 100%);
      position: relative;
    }

    .srv-title {
      font-size: 19px;
      font-weight: 600;
      color: #fff;
      margin-bottom: 8px;
    }

    .srv-text {
      font-size: 14px;
      color: #cdd3d8;
      line-height: 1.5;
      margin: 0;
    }

    .srv-btn {
      position: absolute;
      bottom: 15px;
      left: 50%;
      transform: translateX(-50%);
      background: linear-gradient(135deg, #00B0F0, #39FF14);
      color: #000;
      font-weight: 600;
      border-radius: 9999px;
      padding: 6px 18px;
      border: none;
      text-decoration: none;
      transition: all 0.3s ease;
      font-size: 14px;
    }

    .srv-card:hover .srv-btn {
      background: #92D050;
      color: #000;
      box-shadow: 0 0 15px rgba(146,208,80,0.6);
    }

    .srv-card:hover {
      transform: translateY(-8px);
      border-color: #00B0F0;
      box-shadow: 0 16px 40px rgba(0,0,0,0.5);
    }

    /* fade-up on load */
    .srv-card {opacity:0;animation:fadeUp .6s ease forwards;}
    .srv-card:nth-child(1){animation-delay:0.05s;}
    .srv-card:nth-child(2){animation-delay:0.15s;}
    .srv-card:nth-child(3){animation-delay:0.25s;}
    .srv-card:nth-child(4){animation-delay:0.35s;}
    @keyframes fadeUp {from{opacity:0;transform:translateY(12px);} to{opacity:1;transform:translateY(0);} }

    /* Center "View All" */
    .srv-viewall {
      text-align: center;
      margin-top: 40px;
    }
    .srv-viewall a {
      background: linear-gradient(135deg, #00B0F0, #39FF14);
      color: #000;
      border-radius: 9999px;
      padding: 10px 40px;
      font-weight: 600;
      text-decoration: none;
      transition: all 0.3s ease;
    }
    .srv-viewall a:hover {
      background: #92D050;
      box-shadow: 0 0 15px rgba(146,208,80,0.5);
    }

    @media (max-width:768px){
      #kreatazz-services h2{font-size:30px;}
      .srv-card img{height:180px;}
    }
  </style>

